package com.xianqi.phonevalidation;
import android.Manifest;
import android.app.Activity;
import android.content.Intent;
import android.content.pm.PackageManager;
import android.graphics.*;
import android.hardware.camera2.*;
import android.hardware.camera2.params.StreamConfigurationMap;
import android.media.Image;
import android.media.ImageReader;
import android.os.*;
import android.util.Size;
import android.view.*;
import android.widget.*;
import com.google.zxing.Result;
import java.util.*;

/** Native on-device scan, started only by the explicit query-row button. */
public final class BarcodeScanActivity extends Activity {
    private TextureView preview;private TextView message;private Button light;
    private HandlerThread worker;private Handler handler;
    private final Object lock=new Object();private CameraDevice camera;private CameraCaptureSession session;private CaptureRequest.Builder request;private ImageReader reader;private Surface surface;
    private volatile boolean resumed=false,done=false;private int generation=0;private boolean opening=false,torch=false,flash=false;private long lastFrame=0,lastMatch=0;private String lastValue="";private int matches=0;private Size size;
    @Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(0xff102b25);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(0,i.getSystemWindowInsetTop(),0,i.getSystemWindowInsetBottom());return i;});
        message=new TextView(this);message.setText("对准一个条形码，识别后自动返回查询");message.setTextColor(Color.WHITE);message.setTextSize(16);message.setGravity(Gravity.CENTER);message.setPadding(16,20,16,20);root.addView(message);
        FrameLayout frame=new FrameLayout(this);preview=new TextureView(this);frame.addView(preview,new FrameLayout.LayoutParams(-1,-1));View guide=new View(this){final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);@Override protected void onDraw(Canvas c){p.setColor(0xccb5e7d0);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(3*getResources().getDisplayMetrics().density);float l=getWidth()*.08f,r=getWidth()*.92f,t=getHeight()*.35f,b=getHeight()*.65f;c.drawRoundRect(l,t,r,b,14,14,p);}};frame.addView(guide,new FrameLayout.LayoutParams(-1,-1));root.addView(frame,new LinearLayout.LayoutParams(-1,0,1));
        LinearLayout buttons=new LinearLayout(this);buttons.setPadding(16,16,16,20);buttons.addView(WarehouseUi.button(this,"返回",false,v->finish()),new LinearLayout.LayoutParams(0,-2,1));light=WarehouseUi.button(this,"补光",false,v->{torch=!torch;repeat();});light.setEnabled(false);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMarginStart(12);buttons.addView(light,lp);root.addView(buttons);setContentView(root);
        preview.setSurfaceTextureListener(new TextureView.SurfaceTextureListener(){public void onSurfaceTextureAvailable(SurfaceTexture s,int w,int h){open();}public void onSurfaceTextureSizeChanged(SurfaceTexture s,int w,int h){transform();}public boolean onSurfaceTextureDestroyed(SurfaceTexture s){close();return true;}public void onSurfaceTextureUpdated(SurfaceTexture s){}});
    }
    @Override protected void onResume(){super.onResume();done=false;matches=0;lastValue="";resumed=true;worker=new HandlerThread("库管扫码");worker.start();handler=new Handler(worker.getLooper());if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.CAMERA},61);else if(preview.isAvailable())open();}
    @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] grants){super.onRequestPermissionsResult(code,permissions,grants);if(code==61&&grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED)open();else message.setText("未获相机权限，可返回后手动输入查询。");}
    private void open(){if(!resumed||done||!preview.isAvailable()||checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)return;synchronized(lock){if(opening||camera!=null)return;opening=true;}
        try{CameraManager manager=(CameraManager)getSystemService(CAMERA_SERVICE);String id=null;CameraCharacteristics info=null;for(String candidate:manager.getCameraIdList()){CameraCharacteristics c=manager.getCameraCharacteristics(candidate);if(Integer.valueOf(CameraCharacteristics.LENS_FACING_BACK).equals(c.get(CameraCharacteristics.LENS_FACING))){id=candidate;info=c;break;}}if(id==null||info==null)throw new Exception();StreamConfigurationMap map=info.get(CameraCharacteristics.SCALER_STREAM_CONFIGURATION_MAP);if(map==null)throw new Exception();Set<Size> textures=new HashSet<>(Arrays.asList(map.getOutputSizes(SurfaceTexture.class)));Size best=null;long score=Long.MAX_VALUE;for(Size s:map.getOutputSizes(ImageFormat.YUV_420_888)){long area=(long)s.getWidth()*s.getHeight();if(!textures.contains(s)||area>1280L*960)continue;long value=Math.abs(area-1280L*720);if(value<score){score=value;best=s;}}if(best==null)throw new Exception();size=best;flash=Boolean.TRUE.equals(info.get(CameraCharacteristics.FLASH_INFO_AVAILABLE));int ticket=generation;Handler background=handler;transform();
            manager.openCamera(id,new CameraDevice.StateCallback(){public void onOpened(CameraDevice value){synchronized(lock){if(!resumed||ticket!=generation){value.close();return;}opening=false;camera=value;}configure(value,ticket,background);}public void onDisconnected(CameraDevice value){value.close();problem("相机连接中断，请返回后重试。");}public void onError(CameraDevice value,int error){value.close();problem("相机打开失败，请检查权限或关闭占用相机的应用。");}},background);
        }catch(Exception error){synchronized(lock){opening=false;}problem("未能打开后置相机，可返回后手动输入查询。");}
    }
    private void configure(CameraDevice device,int ticket,Handler background){try{synchronized(lock){if(!resumed||ticket!=generation)return;SurfaceTexture texture=preview.getSurfaceTexture();if(texture==null)return;texture.setDefaultBufferSize(size.getWidth(),size.getHeight());surface=new Surface(texture);reader=ImageReader.newInstance(size.getWidth(),size.getHeight(),ImageFormat.YUV_420_888,2);BarcodeDecoder decoder=new BarcodeDecoder();reader.setOnImageAvailableListener(source->{try(Image image=source.acquireLatestImage()){if(image==null||!resumed||done||ticket!=generation)return;long now=SystemClock.elapsedRealtime();if(now-lastFrame<180)return;lastFrame=now;Image.Plane y=image.getPlanes()[0];Result value=decoder.decode(BarcodeDecoder.luminance(y.getBuffer(),y.getRowStride(),y.getPixelStride(),image.getWidth(),image.getHeight()),image.getWidth(),image.getHeight());if(value==null){matches=0;return;}String key=value.getBarcodeFormat()+":"+value.getText();matches=key.equals(lastValue)&&now-lastMatch<1800?matches+1:1;lastValue=key;lastMatch=now;if(matches>=2){done=true;runOnUiThread(()->{if(resumed&&ticket==generation){setResult(RESULT_OK,new Intent().putExtra("value",value.getText()).putExtra("format",value.getBarcodeFormat().name()));finish();}});}}catch(Exception ignored){}},background);
                request=device.createCaptureRequest(CameraDevice.TEMPLATE_PREVIEW);request.addTarget(surface);request.addTarget(reader.getSurface());request.set(CaptureRequest.CONTROL_AF_MODE,CaptureRequest.CONTROL_AF_MODE_CONTINUOUS_PICTURE);request.set(CaptureRequest.CONTROL_AE_MODE,CaptureRequest.CONTROL_AE_MODE_ON);device.createCaptureSession(Arrays.asList(surface,reader.getSurface()),new CameraCaptureSession.StateCallback(){public void onConfigured(CameraCaptureSession value){synchronized(lock){if(!resumed||ticket!=generation){value.close();return;}session=value;}repeat();runOnUiThread(()->light.setEnabled(flash));}public void onConfigureFailed(CameraCaptureSession value){problem("相机预览未能启动，请返回后重试。");}},background);}}
        catch(Exception error){problem("相机预览未能启动，可返回后手动查询。");}}
    private void repeat(){synchronized(lock){if(session==null||request==null||handler==null||!resumed)return;try{request.set(CaptureRequest.FLASH_MODE,torch&&flash?CaptureRequest.FLASH_MODE_TORCH:CaptureRequest.FLASH_MODE_OFF);session.setRepeatingRequest(request.build(),null,handler);}catch(Exception error){problem("相机状态已变化，请返回后重试。");}}}
    private void transform(){if(size==null||!preview.isAvailable())return;int rotation=getWindowManager().getDefaultDisplay().getRotation();Matrix matrix=new Matrix();float cx=preview.getWidth()/2f,cy=preview.getHeight()/2f;if(rotation==Surface.ROTATION_90||rotation==Surface.ROTATION_270){RectF view=new RectF(0,0,preview.getWidth(),preview.getHeight()),buffer=new RectF(0,0,size.getHeight(),size.getWidth());buffer.offset(cx-buffer.centerX(),cy-buffer.centerY());matrix.setRectToRect(view,buffer,Matrix.ScaleToFit.FILL);float scale=Math.max((float)preview.getHeight()/size.getHeight(),(float)preview.getWidth()/size.getWidth());matrix.postScale(scale,scale,cx,cy);matrix.postRotate(90*(rotation-2),cx,cy);}else if(rotation==Surface.ROTATION_180)matrix.postRotate(180,cx,cy);preview.setTransform(matrix);}
    private void problem(String value){runOnUiThread(()->{if(!isFinishing())message.setText(value);});}
    private void close(){synchronized(lock){generation++;opening=false;if(session!=null){session.close();session=null;}if(camera!=null){camera.close();camera=null;}if(reader!=null){reader.close();reader=null;}if(surface!=null){surface.release();surface=null;}request=null;}}
    @Override protected void onPause(){resumed=false;close();if(worker!=null)worker.quitSafely();worker=null;handler=null;super.onPause();}
}
